\label{imhd}
Assume that the initial data $({\bf u}(x,t),{\bf H}(x,t))|_{t=0} = ({\bf u}_0(x),
\linebreak  {\bf H}_0(x))$ satisfy ${\bf u}_0, {\bf H}_0\in
 {H}^s $, $s>d/2+1$, and ${\rm div } {\bf u}_0=0, {\rm div } {\bf H}_0=0$. Then, there exist a
 $T^*\in (0,\infty)$ and a unique solution
 $({\bf u},{\bf H})\in L^{\infty}([0,T^*),{H}^s)$ to the ideal
incompressible MHD equations \eqref{a2l}-\eqref{a2n}
satisfying, for any $0<T<T^*$, ${\rm div } {\bf u} =0$, ${\rm div }{\bf H} =0$, and
\begin{equation}\label{ba}
\sup_{0\le t\le T}\!\big\{\|({\bf u},{\bf H})(t)\|_{H^s}
+\|(\partial_t{\bf u},\partial_t{\bf H})(t)\|_{H^{s-1}}\big\} \le C_T.
\end{equation}

\label{cmhd}
 Let $\gamma>d/2$. Supposing that the initial data
 $(\rho^\epsilon_0,\mathbf{m}^\epsilon_0,{\bf H}^\epsilon_0 )$ satisfy the assumptions \eqref{bc}-\eqref{bd},
 then the compressible MHD equations
 \eqref{a2i}-\eqref{a2k} with  the initial data \eqref{bb} enjoy
  at least one global weak solution $(\rho^\epsilon,  {\bf u}^\epsilon, {\bf H}^\epsilon)$
 satisfying
\begin{enumerate}
  \item  $ \rho^\epsilon-1\in L^\infty(0,\infty;L^\gamma_2)\cap
 C([0,\infty),L^r_2)$ for all $1\leq r< \gamma$, $\rho^\epsilon
 |{\bf u}^\epsilon|^2\in
  L^\infty(0,\infty; L^1)$, ${\bf H}^\epsilon
\in   L^\infty(0,\infty; L^2)$, ${\bf u}^\epsilon\in L^2(0,T;H^1),$
  $\rho^\epsilon{\bf u}^\epsilon\in C([0,T],  L^{\frac{2\gamma}{\gamma+1}}_{weak})$,
  and  ${\bf H}^\epsilon \in  L^2(0,T;H^1)\cap C([0,T],L^{\frac{2\gamma}{\gamma+1}}_{weak})$
   for all $T\in (0,\infty)$;

  \item  the energy inequality
  \begin{equation}\label{be}
   \mathcal{E}^\epsilon(t)+\int^t_0  \mathcal{D}^\epsilon(s)ds\leq
 \mathcal{E}^\epsilon(0)
  \end{equation}
  holds with the finite total energy
  \begin{equation}\label{bf}
 \qquad\qquad  \mathcal{E}^\epsilon(t)\equiv \int_{\mathbb{R}^d}
 \bigg[\frac12\rho^\epsilon|{\bf u}^\epsilon|^2+\frac12|{\bf H}^\epsilon|^2
        +\frac{a}{\epsilon^2{(\gamma-1)}}\big((\rho^\epsilon)^\gamma
 -1-\gamma (\rho^\epsilon-1)\big)
    \bigg](t)
   \end{equation}
   and the dissipation energy
\begin{equation}\label{bff}
\mathcal{D}^\epsilon(t)\equiv \int_{\mathbb{R}^d}\big[ \mu^\epsilon|\nabla
 {\bf u}^\epsilon|^2
 +(\mu^\epsilon+\lambda^\epsilon) |{\rm div}{\bf u}^\epsilon|^2 + \nu^\epsilon |\nabla
 {\bf H}^\epsilon|^2\big](t);
\end{equation}


  \item the continuity equation is satisfied in the sense of
 renormalized solutions, i.e.,
  \begin{equation} \label{cnsbg}
    \partial_t b(\rho^\epsilon)+{ \rm div}
 (b(\rho^\epsilon){\bf u}^\epsilon)+\big(b'(\rho^\epsilon)\rho^\epsilon-b(\rho^\epsilon)\big){\rm div}
 {\bf u}^\epsilon =0
  \end{equation}
  for any $b\in C^1(\mathbb{R})$ such that $b'(z)$ is a constant for
 $z$ large enough;
  \item the equations \eqref{a2i}-\eqref{a2k} hold in
 $\mathcal{D}'( \mathbb{R}^d\times(0,\infty))$.
\end{enumerate}

\label{MRa} Let $s>{d}/{2}+2$ and the conditions in Proposition \ref{cmhd} hold.
Assume that the shear viscosity $\mu^\epsilon$
and the magnetic diffusion coefficient $\nu^\epsilon $ satisfy
\begin{align}\label{abc}
  \mu^\epsilon =\epsilon^\alpha,\quad \nu^\epsilon=\epsilon^\beta
\end{align}
for some constants $\alpha , \beta>0$ satisfying $0<\alpha+\beta
<2$.
  Moreover we
 assume that
$\sqrt{\rho^\epsilon_0}{\bf u}^\epsilon_0$ converges strongly in $L^2$ to
some $\tilde{{\bf u}}_0$, ${\bf H}^\epsilon_0$ converges strongly in $L^2$ to
some ${\bf H}_0$, and $\Pi^\epsilon_0$ converges strongly in $L^2$ to
some $\varphi_0$. Let $({\bf u},{\bf H})$ be the smooth solution to the ideal
incompressible MHD equations \eqref{a2l}-\eqref{a2n}
defined on $[0,T^*)$ with $({\bf u},{\bf H})|_{t=0}=({\bf u}_0,{\bf H}_0), {\bf u}_0=P\tilde{
{\bf u}}_0$. Then, for any $0<T<T^*$, the global weak solution
$(\rho^\epsilon, {\bf u}^\epsilon, {\bf H}^\epsilon)$ of the compressible
MHD equations \eqref{a2i}-\eqref{a2k} established in
Proposition \ref{cmhd} satisfies
\begin{enumerate}
          \item  $\rho^\epsilon$ converges strongly to $1$ in
 $C([0,T],L^\gamma_2(\mathbb{R}^d))$;
           \item  ${\bf H}^\epsilon$ converges strongly to $  {\bf H}$
  in $L^\infty (0,T;L^2(\mathbb{R}^d))$;
          \item $P(\sqrt{\rho^\epsilon}{\bf u}^\epsilon)$ converges  strongly
 to ${\bf u}$ in $L^\infty (0,T;L^2(\mathbb{R}^d))$;
           \item $\sqrt{\rho^\epsilon}{\bf u}^\epsilon$ converges strongly to
 ${\bf u}$ in $L^r(0,T; L^2_{\mathrm{loc}}(\mathbb{R}^d))$ for all $1\leq r<+\infty$.
          \end{enumerate}

Our arguments in this paper can be applied, after slight
modifications,
 to the case
 \begin{equation*}
  \mu^\epsilon\rightarrow \mu^0,    \quad   \nu^\epsilon \rightarrow \nu^0 \quad \text{as}\quad
\epsilon \rightarrow 0,
\end{equation*}
 where $\mu^0 $ and $ \nu^0$ are nonnegative constants satisfying
(1) $\mu_0>0, \nu^0=0$, or (2) $\mu_0=0, \nu^0>0$ or  (3) $\mu_0>0,
\nu^0>0$.  Hence we can also obtain the convergence of
  compressible MHD equations \eqref{a2i}-\eqref{a2k} to the incompressible MHD
  equations
\begin{align*}
& \partial_t {\bf u}+({\bf u}\cdot \nabla){\bf u} -({{\bf H}} \cdot \nabla
  ){{\bf H}} -\mu^0 \Delta {\bf u} +\nabla p +\frac12\nabla(|{{\bf H}} |^2) =0,  \\
& \partial_t {{\bf H}}    + ( {{\bf u}}  \cdot \nabla) {{\bf H}}
 - ( {{\bf H}} \cdot \nabla) {{\bf u}} -\nu^0 \Delta {\bf H} =  0, \\
  &{\rm div } {\bf u}=0, \quad   {\rm div } {\bf H}=0.
 \end{align*}
We omit the details for conciseness.
